import assert from 'node:assert/strict';import fs from 'node:fs';import {readWorldBankObservation,observationRequest} from '../functions/_lib/world-bank-observations.js';import {askURL} from '../assets/js/pages/civilization-atlas/world-reading-context.js';import {compareWorldObjects} from '../assets/js/pages/civilization-atlas/world-r42-contract.js';import {resolveSelectedArticle} from '../functions/contextual-ask/contextual-ask-runtime.js';
const rows=[],check=async(id,fn)=>{await fn();rows.push({id,state:'PASS'});};const q={country:'MY',indicator:'SP.POP.TOTL',year:2026},payload=()=>[{lastupdated:'2026-10-01'},[{country:{id:'MY',value:'Malaysia'},indicator:{id:q.indicator},date:'2026',value:10,unit:''}]],run=b=>readWorldBankObservation(q,{fetcher:async()=>Response.json(b)});
await check('EXACT_OBJECT_YEAR',async()=>assert.equal((await run(payload())).value,10));for(const [id,change,expected]of [['NULL_NOT_ZERO',b=>b[1][0].value=null,'YEAR_MISSING'],['NO_YEAR_FALLBACK',b=>b[1][0].date='2025','IDENTITY_MISMATCH'],['WRONG_COUNTRY',b=>b[1][0].country.id='CN','IDENTITY_MISMATCH'],['WRONG_INDICATOR',b=>b[1][0].indicator.id='GDP','IDENTITY_MISMATCH'],['WRONG_UNIT',b=>b[1][0].unit='USD','UNIT_MISMATCH']])await check(id,async()=>{const b=payload();change(b);const r=await run(b);assert.equal(r.state,expected);assert.equal(r.value,null);});
await check('WORLD_BANK_ZERO_TOTAL_NULL_PAGE',async()=>assert.equal((await run([{total:0},null])).state,'YEAR_MISSING'));await check('EMPTY_YEAR',async()=>assert.equal((await run([{},[]])).state,'YEAR_MISSING'));await check('TIMEOUT_DISTINCT',async()=>assert.equal((await readWorldBankObservation(q,{fetcher:async()=>{throw new DOMException('timeout','TimeoutError')}})).state,'TIMEOUT'));await check('HTTP_FAILURE_DISTINCT',async()=>assert.equal((await readWorldBankObservation(q,{fetcher:async()=>new Response('',{status:503})})).state,'SERVICE_ERROR'));await check('PRIVATE_INPUT_REJECTED_BEFORE_FETCH',()=>assert.throws(()=>observationRequest({...q,question:'private-marker'}),/PUBLIC_IDENTIFIERS_ONLY/));await check('OUTBOUND_IDENTIFIERS_ONLY',async()=>{await readWorldBankObservation(q,{fetcher:async url=>{assert.deepEqual([...new URL(url).searchParams.keys()],['format','date','per_page']);assert(!url.includes('private'));return Response.json(payload());}});});
await check('ASK_NO_PRIVATE_QUERY',()=>{const u=new URL(askURL({contextType:'KNOWLEDGE',contextRef:'BOOK:BOOK-5',question:'private-marker',contextSummary:'private-marker',contextRoute:'/world/?q=private-marker&atlas=cases&case=CA-T11-02',retrievalScope:{bookCode:'BOOK-5',question:'private-marker'}}),'https://local');assert(!u.href.includes('private-marker'));assert.equal(JSON.parse(u.searchParams.get('retrievalScope')).bookCode,'BOOK-5');});await check('COMPARISON_PRICE_BASE',()=>assert.equal(compareWorldObjects({id:'a',priceBasis:'PPP'},{id:'b',priceBasis:'CURRENT_USD'}).state,'NOT_COMPARABLE'));
await check('ADMITTED_PARAGRAPH_SCHEMA_NOT_DROPPED',async()=>{const env={ASSETS:{fetch:async r=>{try{return new Response(fs.readFileSync(new URL(r.url).pathname.slice(1)))}catch{return new Response('',{status:404})}}}};const a=await resolveSelectedArticle(env,'direction-position-and-coordinates-form-navigation','en');assert.equal(a.bookCode,'BOOK-1');assert(a.sources.length>=7);assert(a.sources.every(s=>s.href.startsWith('/articles/')));assert.equal(await resolveSelectedArticle(env,'../../../private','en'),null);});
fs.writeFileSync('content/production-closure/world-content-convergence-20261019/zero-cost-contracts.json',JSON.stringify({at:new Date().toISOString(),providerCalls:0,networkCalls:0,rows},null,2)+'\n');console.log('PASS',rows.length,'World contracts, source paragraph adapter, privacy and precise observation errors');
